// Class
public class Animal {
    private String name;   // encapsulated field
    protected int age;
    public static int count = 0;

    public Animal(String name, int age) {
        this.name = name;
        this.age  = age;
        count++;
    }

    public String getName() { return name; }  // getter
    public void setName(String n) { this.name = n; }  // setter

    public String speak() { return name + " makes a sound"; }

    @Override
    public String toString() { return "Animal(" + name + ")" ; }
}

// Interface
public interface Flyable {
    double MAX_ALTITUDE = 10000; // public static final
    void fly();                  // abstract
    default void land() { System.out.println("Landing..."); }
}

// Inheritance & multiple interface implementation
public class Dog extends Animal implements Flyable {
    private String breed;

    public Dog(String name, int age, String breed) {
        super(name, age);
        this.breed = breed;
    }

    @Override
    public String speak() { return getName() + " says Woof!"; }

    @Override
    public void fly() { System.out.println("Dogs can't fly!"); }
}

Dog d = new Dog("Rex", 3, "Lab");
System.out.println(d.speak());
System.out.println(d instanceof Animal);  // true
