// Checked vs unchecked exceptions
// Checked: must declare or catch (IOException, SQLException)
// Unchecked: extend RuntimeException (NullPointerException, etc.)

// try / catch / finally
try {
    int result = 10 / 0;
    String s = null;
    s.length();  // NullPointerException
} catch (ArithmeticException e) {
    System.err.println("Math error: " + e.getMessage());
} catch (NullPointerException | IllegalArgumentException e) {
    System.err.println("Pointer or arg error: " + e.getMessage());
} catch (Exception e) {
    e.printStackTrace();
} finally {
    System.out.println("Always runs");
}

// try-with-resources (auto-close Closeable)
try (var reader = new BufferedReader(new FileReader("file.txt"));
     var writer = new FileWriter("out.txt")) {
    String line;
    while ((line = reader.readLine()) != null)
        writer.write(line + "\n");
} catch (IOException e) {
    e.printStackTrace();
}

// Custom exception
public class InsufficientFundsException extends RuntimeException {
    private final double amount;
    public InsufficientFundsException(double amount) {
        super("Cannot withdraw: " + amount);
        this.amount = amount;
    }
    public double getAmount() { return amount; }
}

// Throw
throw new InsufficientFundsException(500.0);
